from pathlib import Path
p=Path("sticker-studio.html")
s=p.read_text()
def swap(old,new):
 global s
 assert old in s, "Missing anchor: "+old[:65]
 s=s.replace(old,new,1)
swap('</head>','<link rel="stylesheet" href="./sticker-six-layout.css"></head>')
swap('<label class="field optional-field"><span>العمر</span><input id="patientAge" autocomplete="off" placeholder="مثال: 8 سنوات"></label>','<label class="field"><span>العمر</span><div class="age-control"><input id="patientAge" type="number" min="0" value="6"><select id="ageUnit"><option value="years">سنة</option><option value="months">شهر</option></select></div></label>')
swap('<label class="field optional-field"><span>الوزن</span>','<label class="field"><span>الوزن</span>')
start=s.index('<label class="field optional-field"><span>حساسية / حالة خاصة</span>')
end=s.index('</label>',start)+len('</label>')
s=s[:start]+'''<div class="safety-choices"><fieldset><legend>حامل؟</legend><label><input type="radio" name="pregnancy" value="yes"> نعم</label><label><input type="radio" name="pregnancy" value="no"> لا</label></fieldset><fieldset><legend>رضاعة؟</legend><label><input type="radio" name="breastfeeding" value="yes"> نعم</label><label><input type="radio" name="breastfeeding" value="no"> لا</label></fieldset></div>'''+s[end:]
swap('<div class="preview-grid" id="previewGrid"></div>','<div class="preview-grid" id="previewGrid"></div><div class="sticker-pager"><button class="btn small" id="stickerPrev" type="button">السابق</button><span id="stickerPageCount">1 / 1</span><button class="btn small" id="stickerNext" type="button">التالي</button></div>')
swap("const state={patient:{name:'',phone:'',age:'',weight:'',safety:''},","let stickerPage=0;\nconst state={patient:{name:'',phone:'',age:'6',ageUnit:'years',weight:'',pregnancy:'',breastfeeding:''},")
swap("pregnancy:state.patient.safety==='pregnant',breastfeeding:state.patient.safety==='breastfeeding'","pregnancy:state.patient.pregnancy==='yes',breastfeeding:state.patient.breastfeeding==='yes',ageUnit:state.patient.ageUnit")
swap("state.medications.filter(m=>m.selected!==false).map(m=>\`<div class=\"sticker-preview", "state.medications.slice(stickerPage*6,stickerPage*6+6).map(m=>\`<div data-med-id=\"${esc(m.id)}\" role=\"button\" tabindex=\"0\" class=\"sticker-preview ${m.selected===false?'sticker-unselected':''}")
swap("if(!state.approved){toast('موافقة الصيدلي إلزامية قبل الطباعة'","if(!['yes','no'].includes(state.patient.pregnancy)||!['yes','no'].includes(state.patient.breastfeeding)){toast('حدد الحمل والرضاعة قبل الطباعة','err');return null}if(!state.approved){toast('موافقة الصيدلي إلزامية قبل الطباعة'")
old="['patientName','patientPhone','patientAge','patientWeight','patientSafety'].forEach(id=>$(id).addEventListener('input',()=>{state.patient={name:$('patientName').value,phone:$('patientPhone').value,age:$('patientAge').value,weight:$('patientWeight').value,safety:$('patientSafety').value};persist();renderPreview()}));"
new="""['patientName','patientPhone','patientAge','patientWeight','ageUnit'].forEach(id=>$(id).addEventListener('input',()=>{state.patient.name=$('patientName').value;state.patient.phone=$('patientPhone').value;state.patient.age=$('patientAge').value;state.patient.weight=$('patientWeight').value;state.patient.ageUnit=$('ageUnit').value;persist();renderPreview()}));for(const name of ['pregnancy','breastfeeding'])document.querySelectorAll('input[name="'+name+'"]').forEach(el=>el.addEventListener('change',()=>{state.patient[name]=el.value;state.approved=false;$('pharmacistApproval').checked=false;persist()}));$('stickerPrev').onclick=()=>{stickerPage=Math.max(0,stickerPage-1);renderPreview()};$('stickerNext').onclick=()=>{stickerPage=Math.min(Math.max(0,Math.ceil(state.medications.length/6)-1),stickerPage+1);renderPreview()};const grid=$('previewGrid');let x=null;grid.addEventListener('touchstart',e=>{x=e.touches[0].clientX},{passive:true});grid.addEventListener('touchend',e=>{if(x===null)return;const dx=e.changedTouches[0].clientX-x;x=null;if(Math.abs(dx)>45){stickerPage=Math.max(0,Math.min(Math.ceil(state.medications.length/6)-1,stickerPage+(dx>0?1:-1)));renderPreview()}},{passive:true});grid.addEventListener('click',e=>{const card=e.target.closest('[data-med-id]');if(!card)return;const m=state.medications.find(m=>m.id===card.dataset.medId);if(m){m.selected=m.selected===false;persist();renderPreview()}});grid.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.target.click()}});"""
swap(old,new)
swap("function renderPreview(){const[w,h]=dimensions();","function renderPreview(){const pages=Math.max(1,Math.ceil(state.medications.length/6));stickerPage=Math.min(stickerPage,pages-1);$('stickerPageCount').textContent=(stickerPage+1)+' / '+pages;$('stickerPrev').disabled=stickerPage===0;$('stickerNext').disabled=stickerPage===pages-1;const[w,h]=dimensions();")
swap("state.patient={name:'',phone:'',age:'',weight:'',safety:''}","state.patient={name:'',phone:'',age:'6',ageUnit:'years',weight:'',pregnancy:'',breastfeeding:''}")
swap(";$('patientSafety').value=state.patient.safety",";$('ageUnit').value=state.patient.ageUnit||'years';for(const name of ['pregnancy','breastfeeding'])document.querySelectorAll('input[name="'+name+'"]').forEach(el=>el.checked=el.value===state.patient[name])")
p.write_text(s)
print("Patched Sticker Studio",len(s))
